import csv, re
from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP, ROUND_HALF_EVEN
from pathlib import Path

root = Path('data')
HOURS = list(range(1, 25))
PEAK = list(range(7, 23))
_RANGE = re.compile(r'^HE(\d{1,2})(?:-HE(\d{1,2}))?$')

def shape_hours(shape):
    shape = shape.strip().upper()
    if shape == 'ATC':
        return list(HOURS)
    if shape == 'PEAK':
        return list(PEAK)
    if shape == 'OFFPEAK':
        return [he for he in HOURS if he not in PEAK]
    m = _RANGE.match(shape)
    first = int(m.group(1)); last = int(m.group(2) or first)
    return list(range(first, last + 1))

def load_governing(day):
    rows = list(csv.DictReader(open(root/'trades'/'blotter.csv', newline='', encoding='utf-8')))
    best = {}
    for r in rows:
        tid = r['trade_id']
        ver = int(r['version'])
        if tid not in best or ver > best[tid][0]:
            best[tid] = (ver, r)
    trades = []
    for ver, r in best.values():
        if r['status'].strip().upper() != 'ACTIVE':
            continue
        if r['operating_day'] != day:
            continue
        trades.append(r)
    return trades

def net_mw(trades):
    net = defaultdict(lambda: {he: Decimal('0') for he in HOURS})
    for r in trades:
        sign = Decimal('1') if r['side'].strip().upper()=='BUY' else Decimal('-1')
        mw = Decimal(r['mw'])
        for he in shape_hours(r['shape']):
            net[r['settlement_point']][he] += sign * mw
    return net

def load_prices(day):
    by = defaultdict(list)
    for r in csv.DictReader(open(root/'prices'/f'{day}.csv', newline='', encoding='utf-8')):
        by[r['settlement_point']].append((int(r['hour_ending']), int(r['interval']), r['dst_flag'], Decimal(r['price'])))
    return by

def load_stmt(day, rt_only=True):
    totals = defaultdict(lambda: Decimal('0'))
    for r in csv.DictReader(open(root/'statements'/f'{day}.csv', newline='', encoding='utf-8')):
        if rt_only and r['charge_type'] != 'RT_ENERGY':
            continue
        if not rt_only and not r['settlement_point'].strip():
            continue
        if not r['settlement_point'].strip():
            continue
        totals[r['settlement_point']] += Decimal(r['amount'])
    return totals

def q(amount, mode):
    return amount.quantize(Decimal('0.01'), rounding=mode)

def settle(day, mode, per_interval=True):
    trades = load_governing(day)
    net = net_mw(trades)
    prices = load_prices(day)
    amounts = {}
    for point, series in prices.items():
        total = Decimal('0')
        mw = net.get(point, {})
        for he, iv, dst, price in series:
            raw = mw.get(he, Decimal('0')) * Decimal('0.25') * price
            if per_interval:
                total += q(raw, mode)
            else:
                total += raw
        if not per_interval:
            total = q(total, mode)
        amounts[point] = total
    return amounts

days = ['2026-03-06','2026-03-08','2026-03-09','2026-10-30','2026-11-01','2026-11-02']
for label, mode, per in [
    ('interval HALF_UP', ROUND_HALF_UP, True),
    ('interval HALF_EVEN', ROUND_HALF_EVEN, True),
    ('total HALF_UP', ROUND_HALF_UP, False),
    ('total HALF_EVEN', ROUND_HALF_EVEN, False),
]:
    print('====', label)
    breaks = 0
    for day in days:
        shadow = settle(day, mode, per)
        stmt = load_stmt(day, True)
        for point in sorted(set(shadow)|set(stmt)):
            d = shadow.get(point, Decimal('0')) - stmt.get(point, Decimal('0'))
            if d != 0:
                breaks += 1
                print(f'  {day} {point} shadow {shadow.get(point)} stmt {stmt.get(point)} diff {d}')
    print('  breaks', breaks)
